"""Literal offline Kannada rows for the user agreement."""

AGREEMENT_KANNADA_ROWS: dict[str, tuple[str, ...]] = {
    "kn": (
        "ಬಳಕೆದಾರರ ಒಪ್ಪಂದ",
        "Go and Help ಬಳಸುವ ಮೂಲಕ ನೀವು ಒಪ್ಪಿಕೊಳ್ಳುವ ನಿಯಮಗಳು.",
        "1 ಜೂನ್ 2024ರಂದು ನವೀಕರಿಸಲಾಗಿದೆ ಮತ್ತು ಜಾರಿಗೆ ಬಂದಿದೆ",
        "Go and Help ಒಂದು ವೇದಿಕೆ ಮತ್ತು ಮಧ್ಯವರ್ತಿ ಮಾತ್ರ. ಯಾವುದೇ ಬಳಕೆದಾರ, ಕೆಲಸ, ಪ್ರತಿಫಲ ಅಥವಾ ಭೇಟಿಯನ್ನು ನಾವು ಪರಿಶೀಲಿಸುವುದಿಲ್ಲ, ಹಿನ್ನೆಲೆ ತಪಾಸಣೆ ಮಾಡುವುದಿಲ್ಲ, ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡುವುದಿಲ್ಲ, ನೇಮಿಸಿಕೊಳ್ಳುವುದಿಲ್ಲ ಅಥವಾ ಖಾತರಿಪಡಿಸುವುದಿಲ್ಲ. ಇಲ್ಲಿ ನೀವು ಏರ್ಪಡಿಸುವ ಎಲ್ಲವೂ ಸ್ವತಂತ್ರ ವಯಸ್ಕರೊಂದಿಗೆ ನಿಮ್ಮದೇ ಅಪಾಯದಲ್ಲಿ ನಡೆಯುತ್ತದೆ.",
        "Go and Help ಎಂದರೇನು—ಮತ್ತು ಏನಲ್ಲ",
        "Go and Help ಎನ್ನುವುದು ವಯಸ್ಕರು ಪ್ರಾಯೋಗಿಕ ಸಹಾಯಕ್ಕಾಗಿ ವಿನಂತಿಗಳನ್ನು ಪ್ರಕಟಿಸಿ ಪರಸ್ಪರರನ್ನು ಕಂಡುಕೊಳ್ಳುವ ಸ್ಥಳ. ನಾವು ಪ್ರಕಟಣೆ, ನಕ್ಷೆ, ಸಂದೇಶ ಮತ್ತು ವೇದಿಕೆಯ ಸಾಧನಗಳನ್ನು ಒದಗಿಸುತ್ತೇವೆ. ನಮ್ಮ ಪಾತ್ರ ಅಷ್ಟೇ.",
        "ಬಳಕೆದಾರರ ನಡುವಿನ ಯಾವುದೇ ಏರ್ಪಾಟಿನಲ್ಲಿ ನಾವು ಪಕ್ಷಕಾರರಲ್ಲ. ನಾವು ಉದ್ಯೋಗದಾತ, ಉದ್ಯೋಗ ಸಂಸ್ಥೆ, ಸಿಬ್ಬಂದಿ ನೇಮಕಾತಿ ಸಂಸ್ಥೆ, ಗುತ್ತಿಗೆದಾರ, ವಿಮಾದಾರ, ಎಸ್ಕ್ರೋ ಸೇವೆ, ಹಿನ್ನೆಲೆ ಪರಿಶೀಲನೆ ಪೂರೈಕೆದಾರ, ಪ್ರಯಾಣ ಸಂಸ್ಥೆ ಅಥವಾ ಮೇಲ್ವಿಚಾರಕರಲ್ಲ. ಗುರುತಿನ ದಾಖಲೆ, ಅರ್ಹತೆ, ಪರವಾನಗಿ, ವಿಮೆ, ಅಪರಾಧ ದಾಖಲೆ, ವಲಸೆ ಸ್ಥಿತಿ ಅಥವಾ ತೆರಿಗೆ ಸ್ಥಿತಿಯನ್ನು ಪರಿಶೀಲಿಸುವುದಿಲ್ಲ; ಪ್ರಕಟಣೆ ಅಥವಾ ಪ್ರೊಫೈಲ್‌ನಲ್ಲಿರುವ ವಿಷಯ ಸತ್ಯವೆಂದೂ ದೃಢಪಡಿಸುವುದಿಲ್ಲ.",
        "ಅರ್ಹತೆ",
        "ನಿಮಗೆ ಕನಿಷ್ಠ 16 ವರ್ಷ ವಯಸ್ಸಾಗಿರಬೇಕು ಮತ್ತು ಈ ಒಪ್ಪಂದಕ್ಕೆ ಕಾನೂನುಬದ್ಧವಾಗಿ ಒಪ್ಪುವ ಸಾಮರ್ಥ್ಯವಿರಬೇಕು. ಒಬ್ಬರಿಗೆ ಒಂದು ಖಾತೆ ಮಾತ್ರ. ನ್ಯಾಯಾಲಯ, ನಿರ್ಬಂಧ ವ್ಯವಸ್ಥೆ ಅಥವಾ ಅನ್ವಯಿಸುವ ಕಾನೂನು ನಿಷೇಧಿಸಿದರೆ, ಅಥವಾ ನಿಮ್ಮ ಪ್ರವೇಶವನ್ನು ನಾವು ಹಿಂದೆ ತೆಗೆದುಹಾಕಿದ್ದರೆ Go and Help ಬಳಸಬಾರದು.",
        "ನಿಮ್ಮ ಖಾತೆ",
        "ನಿಮ್ಮ ಪಾಸ್‌ವರ್ಡ್ ರಹಸ್ಯವಾಗಿಡಿ ಮತ್ತು ಇಮೇಲ್ ವಿಳಾಸವನ್ನು ನವೀಕೃತವಾಗಿಡಿ. ನಿಮ್ಮ ಖಾತೆಯ ಮೂಲಕ ನಡೆಯುವ ಎಲ್ಲವನ್ನೂ ನೀವು ಮಾಡಿದಂತೆ ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ. ಅನಧಿಕೃತ ಪ್ರವೇಶದ ಅನುಮಾನ ಬಂದರೆ ತಕ್ಷಣ ನಮಗೆ ತಿಳಿಸಿ.",
        "ನಿಮ್ಮ ಬಗ್ಗೆ ನಿಖರ ಮಾಹಿತಿ ನೀಡಿ. ಬೇರೆಯವರಂತೆ ನಟಿಸಬೇಡಿ, ಇನ್ನೊಬ್ಬರ ಪರವಾಗಿ ಖಾತೆ ತೆರೆಯಬೇಡಿ ಮತ್ತು ಬೇರೆಯವರ ಫೋಟೋ ಅಥವಾ ಗುರುತನ್ನು ಬಳಸಬೇಡಿ.",
        "ನಿಮ್ಮ ವಿಷಯ",
        "ನೀವು ಬರೆಯುವ ಮತ್ತು ಅಪ್‌ಲೋಡ್ ಮಾಡುವ ವಿಷಯದ ಮಾಲೀಕತ್ವ ನಿಮ್ಮಲ್ಲೇ ಇರುತ್ತದೆ. ಪ್ರಕಟಿಸುವ ಮೂಲಕ, ಸೇವೆಯೊಳಗೆ ಆ ವಿಷಯವನ್ನು ಹೋಸ್ಟ್ ಮಾಡಲು, ಸಂಗ್ರಹಿಸಲು, ಮರುಪ್ರತಿಗಳನ್ನು ಮಾಡಲು, ಪ್ರದರ್ಶನಕ್ಕೆ ಹೊಂದಿಸಲು ಮತ್ತು ತೋರಿಸಲು Go and Help ಗೆ ವಿಶ್ವವ್ಯಾಪಿ, ಅನನ್ಯವಲ್ಲದ, ರಾಯಲ್ಟಿ-ಮುಕ್ತ ಪರವಾನಗಿಯನ್ನು ನೀಡುತ್ತೀರಿ; ಇದರಿಂದ ಅಪ್ಲಿಕೇಶನ್ ಕಾರ್ಯನಿರ್ವಹಿಸಬಹುದು. ನಿಮ್ಮ ವಿಷಯವನ್ನು ಯಾವಾಗ ಬೇಕಾದರೂ ಅಳಿಸಬಹುದು; ಇತರರು ಈಗಾಗಲೇ ಉಲ್ಲೇಖಿಸಿದ ಅಥವಾ ಪ್ರತಿಕ್ರಿಯಿಸಿದ ಪ್ರತಿಗಳು ಅವರ ಪ್ರಕಟಣೆಗಳಲ್ಲಿ ಉಳಿಯಬಹುದು.",
        "ಫೋಟೋ ಸೇರಿ ನೀವು ಪ್ರಕಟಿಸುವ ವಿಷಯವನ್ನು ಪ್ರಕಟಿಸುವ ಹಕ್ಕು ನಿಮಗಿದೆ, ಅದು ಯಾರ ಹಕ್ಕನ್ನೂ ಉಲ್ಲಂಘಿಸುವುದಿಲ್ಲ ಮತ್ತು ಯಾವುದೇ ಕಾನೂನನ್ನು ಮುರಿಯುವುದಿಲ್ಲ ಎಂದು ನೀವು ದೃಢಪಡಿಸುತ್ತೀರಿ. ಈ ಒಪ್ಪಂದವನ್ನು ಉಲ್ಲಂಘಿಸುವ ವಿಷಯವನ್ನು ನಾವು ತೆಗೆದುಹಾಕಬಹುದು; ಆದರೆ ವಿಷಯವನ್ನು ಮುಂಚಿತವಾಗಿ ಪರಿಶೀಲಿಸುವುದಿಲ್ಲ ಅಥವಾ ಅನುಮೋದಿಸುವುದಿಲ್ಲ ಮತ್ತು ಬಳಕೆದಾರರು ಪ್ರಕಟಿಸುವ ವಿಷಯಕ್ಕೆ ಹೊಣೆಗಾರರಲ್ಲ.",
        "ಬಳಕೆದಾರರ ನಡುವಿನ ಏರ್ಪಾಟುಗಳು ಅವರದೇ",
        "ಸಹಾಯ ಮಾಡುವುದು ಅಥವಾ ಪಡೆಯುವುದು, ಪ್ರಯಾಣಿಸುವುದು, ಭೇಟಿಯಾಗುವುದು, ಎಲ್ಲಾದರೂ ತಂಗುವುದು ಅಥವಾ ಪ್ರತಿಫಲ ಕೊಡುವುದು ಅಥವಾ ಸ್ವೀಕರಿಸುವುದಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ಒಪ್ಪಂದವನ್ನು ಸಂಬಂಧಿಸಿದ ಬಳಕೆದಾರರೇ ನೇರವಾಗಿ ಮಾಡುತ್ತಾರೆ. ಅದು ಖಾಸಗಿ ಮತ್ತು ಸ್ವತಂತ್ರ ಏರ್ಪಾಟು. Go and Help ಅದರ ಪಕ್ಷವಲ್ಲ, ಅದರಿಂದ ಕಮಿಷನ್ ಪಡೆಯುವುದಿಲ್ಲ ಮತ್ತು ಅದನ್ನು ಜಾರಿಗೊಳಿಸುವುದಿಲ್ಲ.",
        "ಏರ್ಪಾಟು ಸುರಕ್ಷಿತವೇ, ಕಾನೂನುಬದ್ಧವೇ ಮತ್ತು ನಿಮಗೆ ಸೂಕ್ತವೇ ಎಂದು ನಿರ್ಧರಿಸುವ ಹೊಣೆ ನಿಮ್ಮದು. ನಿಮಗೆ ಅನ್ವಯಿಸುವ ಪರವಾನಗಿ, ವಿಮೆ, ಆರೋಗ್ಯ ಮತ್ತು ಸುರಕ್ಷತಾ ಕರ್ತವ್ಯ, ತೆರಿಗೆ ಅಥವಾ ವರದಿ ಕರ್ತವ್ಯಗಳಿಗೂ ನೀವೇ ಹೊಣೆ. ಕೆಲವು ದೇಶಗಳಲ್ಲಿ ಕೆಲವು ಕೆಲಸಗಳಿಗೆ ಅರ್ಹ ಅಥವಾ ಪರವಾನಗಿ ಪಡೆದ ವ್ಯಕ್ತಿ ಅಗತ್ಯ; ಇಲ್ಲಿ ಏನೂ ಅದನ್ನು ಬದಲಾಯಿಸುವುದಿಲ್ಲ.",
        "ಈ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿ ವಿವರಿಸಿದ ಪ್ರತಿಫಲಗಳು ಜನರ ನಡುವಿನ ಸ್ವಯಂಪ್ರೇರಿತ ಧನ್ಯವಾದಗಳ ಸೂಚನೆಗಳು. Go and Help ನಲ್ಲಿರುವ ಯಾವುದೂ ನಿಮ್ಮ ಮತ್ತು ನಮ್ಮ ನಡುವೆ ಅಥವಾ ನಿಮ್ಮ ಮತ್ತು ಮತ್ತೊಬ್ಬ ಬಳಕೆದಾರರ ನಡುವೆ ಉದ್ಯೋಗ ಸಂಬಂಧ, ಪಾಲುದಾರಿಕೆ, ಪ್ರತಿನಿಧಿತ್ವ, ಫ್ರಾಂಚೈಸಿ ಅಥವಾ ಜಂಟಿ ಉದ್ಯಮವನ್ನು ಸೃಷ್ಟಿಸುವುದಿಲ್ಲ.",
        "ಪಾವತಿ ಮತ್ತು ಸದಸ್ಯತ್ವ",
        "Go and Help ಮೂಲಕ ಸಹಾಯ ನೀಡುವುದು ಉಚಿತ. ಸದಸ್ಯತ್ವ ಐಚ್ಛಿಕವಾಗಿದ್ದು, ನಮ್ಮ ಪಾವತಿ ಸಂಸ್ಕಾರಕ Stripe ಮೂಲಕ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುತ್ತದೆ. ದೃಢಪಡಿಸುವ ಮೊದಲು ಬೆಲೆ ತೋರಿಸಲಾಗುತ್ತದೆ. ಮಾಸಿಕ ಸದಸ್ಯತ್ವವು ಪ್ರತಿ ತಿಂಗಳು ಮತ್ತು ವಾರ್ಷಿಕ ಸದಸ್ಯತ್ವವು ಪ್ರತಿ ವರ್ಷ—ನೀವು ರದ್ದುಮಾಡುವವರೆಗೆ—ಸ್ವಯಂಚಾಲಿತವಾಗಿ ನವೀಕರಿಸುತ್ತದೆ.",
        "ಬಿಲ್ಲಿಂಗ್ ಪೋರ್ಟಲ್‌ನಿಂದ ಯಾವಾಗ ಬೇಕಾದರೂ ರದ್ದುಮಾಡಬಹುದು; ಆಗ ನೀವು ಈಗಾಗಲೇ ಪಾವತಿಸಿದ ಅವಧಿ ಮುಗಿಯುವವರೆಗೆ ಪ್ರಯೋಜನಗಳು ಮುಂದುವರಿಯುತ್ತವೆ. ಸ್ಥಳೀಯ ಕಾನೂನು ಬೇರೆ ವಿಧಿಸಿದರೆ ಹೊರತು, ಅವಧಿಯ ಉಳಿದ ಭಾಗಕ್ಕೆ ಮರುಪಾವತಿ ಇರುವುದಿಲ್ಲ. ನೀವು ವಾಸಿಸುವ ಸ್ಥಳದ ಕಾನೂನಿನಡಿ ಹೊಂದಿರುವ ಹಿಂಪಡೆಯುವಿಕೆ ಅಥವಾ ರದ್ದತಿಯ ಹಕ್ಕುಗಳು ಎಂದಿನಂತೆ ಅನ್ವಯಿಸುತ್ತವೆ.",
        "ನಿಮ್ಮ ಕಾರ್ಡ್ ವಿವರಗಳನ್ನು ನಾವು ಎಂದಿಗೂ ನಿರ್ವಹಿಸುವುದಿಲ್ಲ ಅಥವಾ ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ. ಪಾವತಿ ವಿಫಲವಾದರೆ ಅಥವಾ ಹಿಂತಿರುಗಿಸಲ್ಪಟ್ಟರೆ, ಸಮಸ್ಯೆ ಪರಿಹಾರವಾಗುವವರೆಗೆ ಪ್ರೀಮಿಯಂ ಪ್ರಯೋಜನಗಳನ್ನು ತಾತ್ಕಾಲಿಕವಾಗಿ ನಿಲ್ಲಿಸಬಹುದು.",
        "ಸುರಕ್ಷತೆ ನಿಮ್ಮ ಕೈಯಲ್ಲಿದೆ",
        "ಮೊದಲು ಸಾರ್ವಜನಿಕ ಸ್ಥಳದಲ್ಲಿ ಭೇಟಿಯಾಗಿ. ನೀವು ಎಲ್ಲಿಗೆ ಹೋಗುತ್ತೀರಿ ಎಂದು ಯಾರಿಗಾದರೂ ತಿಳಿಸಿ. ಪರಿಶೀಲಿಸಲಾಗದ ಖಾಸಗಿ ವಿಳಾಸಕ್ಕೆ ಹೋಗಬೇಡಿ. ಮತ್ತೊಬ್ಬ ಬಳಕೆದಾರರಿಗೆ ಹಣ, ಠೇವಣಿ, ದಾಖಲೆ ಅಥವಾ ಖಾತೆ ವಿವರ ಕಳುಹಿಸಬೇಡಿ. ಸುರಕ್ಷಿತವಾಗಿ ಮಾಡುವ ಸಾಮರ್ಥ್ಯವಿಲ್ಲದ ಕೆಲಸ ಕೈಗೆತ್ತಿಕೊಳ್ಳಬೇಡಿ; ಪರಿಸ್ಥಿತಿ ಬದಲಾದರೆ ಅಥವಾ ಸರಿಯಿಲ್ಲವೆನಿಸಿದರೆ ತಕ್ಷಣ ನಿಲ್ಲಿಸಿ.",
        "ದೈಹಿಕ, ಕಟ್ಟಡದ ರಚನೆ, ವಿದ್ಯುತ್, ಯಾಂತ್ರಿಕ, ವೈದ್ಯಕೀಯ, ಪ್ರಾಣಿ ಅಥವಾ ಮಕ್ಕಳ ಆರೈಕೆಯ ಕೆಲಸಕ್ಕೆ ಮುನ್ನ ನಿಮ್ಮ ವಿಮೆಯನ್ನು ಪರಿಗಣಿಸಿ. ನೀವು ಭೇಟಿಯಾಗುವ ವ್ಯಕ್ತಿಗೆ ವಿಮೆ ಇದೆಯೇ ಎಂದೂ ಪರಿಗಣಿಸಿ. ತುರ್ತು ಪರಿಸ್ಥಿತಿಯಲ್ಲಿ ಸ್ಥಳೀಯ ತುರ್ತು ಸೇವೆಗಳಿಗೆ ಕರೆಮಾಡಿ—ಸ್ಥಳದಲ್ಲೇ ನಾವು ಸಹಾಯ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ.",
        "ನಿಷೇಧಿತ ವರ್ತನೆ",
        "Go and Help ಅನ್ನು ಯಾವುದೇ ಕಾನೂನುಬಾಹಿರ ಉದ್ದೇಶಕ್ಕೆ ಅಥವಾ ಕಾನೂನುಬಾಹಿರ ಕೆಲಸ ಏರ್ಪಡಿಸಲು ಬಳಸಬೇಡಿ. ನಿರ್ದಿಷ್ಟವಾಗಿ ನಿಷೇಧಿತವು: ಕಿರುಕುಳ, ಬೆದರಿಕೆ, ದ್ವೇಷ ಭಾಷಣ, ತಾರತಮ್ಯ, ಹಿಂಬಾಲಿಸುವುದು, ಲೈಂಗಿಕ ವಿಷಯ ಅಥವಾ ಸೇವೆಗಳು, ಯಾವುದೇ ರೀತಿಯ ಶೋಷಣೆ ಅಥವಾ ಮಾನವ ಕಳ್ಳಸಾಗಣೆ, ಮಕ್ಕಳನ್ನು ಅಪಾಯಕ್ಕೆ ತಳ್ಳುವುದು, ಸಹಾಯವೆಂದು ತೋರಿಸುವ ಬಲವಂತದ ಅಥವಾ ವೇತನವಿಲ್ಲದ ದುಡಿಮೆ, ಆಯುಧಗಳು, ಮಾದಕ ವಸ್ತುಗಳು, ಕಳ್ಳಸಾಗಣೆ, ವಂಚನೆ, ಹಣ ಅಕ್ರಮ ವರ್ಗಾವಣೆ, ಫಿಷಿಂಗ್, ಸ್ಪ್ಯಾಮ್, ಅನುಮತಿಯಿಲ್ಲದ ಮಾಹಿತಿ ಸಂಗ್ರಹಣೆ, ಸಂಬಂಧವಿಲ್ಲದ ವಾಣಿಜ್ಯ ಜಾಹೀರಾತು ಅಥವಾ ಅಪ್ಲಿಕೇಶನ್‌ನ ಭದ್ರತೆ ಮತ್ತು ಕಾರ್ಯಾಚರಣೆಗೆ ಅಡ್ಡಿಪಡಿಸುವುದು.",
        "ಇನ್ನೊಬ್ಬರ ಖಾಸಗಿ ಮಾಹಿತಿಯನ್ನು ಒಪ್ಪಿಗೆಯಿಲ್ಲದೆ ಪ್ರಕಟಿಸಬೇಡಿ; ಯಾರನ್ನಾದರೂ ಹಿಂಬಾಲಿಸಲು, ಗಮನಿಸಲು ಅಥವಾ ಒತ್ತಡ ಹೇರುವುದಕ್ಕೆ ನಕ್ಷೆ ಅಥವಾ ಹುಡುಕಾಟ ಬಳಸಬೇಡಿ.",
        "ಅಮಾನತು ಮತ್ತು ತೆಗೆದುಹಾಕುವಿಕೆ",
        "ಈ ಒಪ್ಪಂದ ಉಲ್ಲಂಘನೆಯಾಗಿದೆ ಎಂದು ಸಮಂಜಸವಾಗಿ ನಂಬಿದರೆ, ಕಾನೂನು ಹಾಗೆ ಕೇಳಿದರೆ ಅಥವಾ ಇತರರಿಗೆ ಅಥವಾ ಸೇವೆಗೆ ಅಪಾಯವಿದ್ದರೆ, ನಾವು ವಿಷಯ ತೆಗೆದುಹಾಕಬಹುದು, ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ಮಿತಿಗೊಳಿಸಬಹುದು, ಖಾತೆಯನ್ನು ಅಮಾನತುಗೊಳಿಸಬಹುದು ಅಥವಾ ಮುಚ್ಚಬಹುದು. ಸಮಂಜಸವೂ ಕಾನೂನುಬದ್ಧವೂ ಆಗಿದ್ದರೆ ಕಾರಣ ತಿಳಿಸುತ್ತೇವೆ ಮತ್ತು ನೀವು ಪ್ರತಿಕ್ರಿಯಿಸಬಹುದು.",
        "ನೀವು ಯಾವಾಗ ಬೇಕಾದರೂ Go and Help ಬಳಸುವುದನ್ನು ನಿಲ್ಲಿಸಿ ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಮುಚ್ಚಬಹುದು.",
        "ಬೌದ್ಧಿಕ ಸ್ವತ್ತು",
        "Go and Help ಹೆಸರು, ಲೋಗೋ, ವಿನ್ಯಾಸ ಮತ್ತು ಸಾಫ್ಟ್‌ವೇರ್ ನಮ್ಮ ಅಥವಾ ನಮ್ಮ ಪರವಾನಗಿದಾರರ ಸ್ವತ್ತು; ಬೌದ್ಧಿಕ ಸ್ವತ್ತು ಕಾನೂನಿನಿಂದ ರಕ್ಷಿತವಾಗಿದೆ. ಅಪ್ಲಿಕೇಶನ್ ಅನುಮತಿಸುವ ರೀತಿಯಲ್ಲಿ ಮಾತ್ರ ಅವನ್ನು ಬಳಸಬಹುದು. ನಕ್ಷೆಯ ದತ್ತಾಂಶ ಮತ್ತು ಮುಕ್ತ-ಮೂಲ ಘಟಕಗಳು ಅವುಗಳ ಸ್ವಂತ ರಚಯಿತರ ಸ್ವತ್ತಾಗಿಯೇ ಉಳಿಯುತ್ತವೆ ಮತ್ತು ತಮ್ಮದೇ ಪರವಾನಗಿಗಳಡಿ ಬಳಸಲ್ಪಡುತ್ತವೆ.",
        "Go and Help ನಲ್ಲಿನ ವಿಷಯ ನಿಮ್ಮ ಹಕ್ಕುಗಳನ್ನು ಉಲ್ಲಂಘಿಸುತ್ತದೆ ಎಂದು ಭಾವಿಸಿದರೆ, ಯಾವ ವಿಷಯ ಮತ್ತು ಎಲ್ಲಿ ಇದೆ ಎಂದು ತಿಳಿಸಿ; ನಾವು ಪರಿಶೀಲಿಸುತ್ತೇವೆ.",
        "ಇರುವಂತೆಯೇ ಒದಗಿಸುವ ಸೇವೆ",
        "Go and Help ಅನ್ನು ‘ಇರುವಂತೆಯೇ’ ಮತ್ತು ‘ಲಭ್ಯವಿರುವಂತೆ’ ಒದಗಿಸಲಾಗುತ್ತದೆ. ನೀವು ವಾಸಿಸುವ ಸ್ಥಳದ ಕಾನೂನು ಅನುಮತಿಸುವ ಗರಿಷ್ಠ ಮಿತಿವರೆಗೆ, ಅಪ್ಲಿಕೇಶನ್ ನಿರಂತರವಾಗಿರುತ್ತದೆ, ದೋಷರಹಿತವಾಗಿರುತ್ತದೆ, ಎಲ್ಲ ದಾಳಿಗಳಿಂದ ಸುರಕ್ಷಿತವಾಗಿರುತ್ತದೆ ಅಥವಾ ನಿರ್ದಿಷ್ಟ ಉದ್ದೇಶಕ್ಕೆ ಸೂಕ್ತವಾಗಿರುತ್ತದೆ ಎಂದು ನಾವು ಖಾತರಿ ನೀಡುವುದಿಲ್ಲ. ಯಾವುದೇ ಬಳಕೆದಾರ ಪ್ರಾಮಾಣಿಕ, ನಿಪುಣ, ವಿಮೆ ಹೊಂದಿದ, ಪರವಾನಗಿ ಪಡೆದ ಅಥವಾ ಸುರಕ್ಷಿತ ಎಂದು; ಯಾವುದೇ ವಿನಂತಿ, ಪ್ರತಿಫಲ ಅಥವಾ ಪ್ರೊಫೈಲ್ ನಿಖರ ಎಂದು; ಅಥವಾ ಯಾವುದೇ ಏರ್ಪಾಟು ಪಾಲಿಸಲಾಗುತ್ತದೆ ಎಂದೂ ಖಾತರಿ ನೀಡುವುದಿಲ್ಲ.",
        "ಸ್ಥಳಗಳು, ದೂರಗಳು, ಲಭ್ಯತೆ ಮತ್ತು ಮೌಲ್ಯಮಾಪನಗಳು ಬಳಕೆದಾರರು ಮತ್ತು ಮೂರನೇ ವ್ಯಕ್ತಿಯ ನಕ್ಷೆ ದತ್ತಾಂಶ ನೀಡಿದಂತೆ ತೋರಿಸಲಾಗುತ್ತವೆ. ಅವು ತಪ್ಪಾಗಿರಬಹುದು ಅಥವಾ ಹಳೆಯದಾಗಿರಬಹುದು.",
        "ಹೊಣೆಗಾರಿಕೆಯ ಮಿತಿ",
        "ನಿಮಗೆ ಅನ್ವಯಿಸುವ ಕಾನೂನು ಅನುಮತಿಸುವ ಗರಿಷ್ಠ ಮಿತಿವರೆಗೆ, ಇತರ ಬಳಕೆದಾರರು, ಅವರ ವರ್ತನೆ ಅಥವಾ ವಿಷಯ, ಬಳಕೆದಾರರ ನಡುವಿನ ಭೇಟಿ ಅಥವಾ ಸಂವಹನ, ಪ್ರಯಾಣ, ಮಾಡಿದ ಅಥವಾ ನಿರಾಕರಿಸಿದ ಕೆಲಸ, ನೀಡಿದ ಅಥವಾ ತಡೆಹಿಡಿದ ಪ್ರತಿಫಲ ಅಥವಾ ಮೂರನೇ ವ್ಯಕ್ತಿಗಳ ಕೃತ್ಯಗಳಿಂದ ಉಂಟಾಗುವ ಅಥವಾ ಅವಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ನಷ್ಟ ಅಥವಾ ಹಾನಿಗೆ Go and Help, ಅದರ ಮಾಲೀಕರು, ಸಿಬ್ಬಂದಿ ಮತ್ತು ಪೂರೈಕೆದಾರರು ಹೊಣೆಗಾರರಾಗುವುದಿಲ್ಲ. ಇದರಲ್ಲಿ ದೈಹಿಕ ಗಾಯ, ಅನಾರೋಗ್ಯ ಅಥವಾ ಮರಣ; ಆಸ್ತಿ ನಷ್ಟ, ಕಳವು ಅಥವಾ ಹಾನಿ; ಹಣಕಾಸು ಅಥವಾ ಆರ್ಥಿಕ ನಷ್ಟ; ಲಾಭ, ಅವಕಾಶ ಅಥವಾ ದತ್ತಾಂಶ ನಷ್ಟ; ಮತ್ತು ದುಃಖ ಅಥವಾ ಇತರ ಭಾವನಾತ್ಮಕ ಹಾನಿ ಸ್ಪಷ್ಟವಾಗಿ ಸೇರಿವೆ.",
        "ಅದೇ ಮಿತಿವರೆಗೆ ಪರೋಕ್ಷ, ಆಕಸ್ಮಿಕ, ವಿಶೇಷ, ಪರಿಣಾಮಾತ್ಮಕ ಅಥವಾ ದಂಡಾತ್ಮಕ ಹಾನಿಗೆ ನಾವು ಹೊಣೆಗಾರರಲ್ಲ. ಕಾನೂನಿನ ಪ್ರಕಾರ ಹೊಣೆಗಾರಿಕೆಯನ್ನು ಸಂಪೂರ್ಣ ಹೊರತುಪಡಿಸಲಾಗದಿದ್ದರೂ ಮಿತಿಗೊಳಿಸಬಹುದಾದಲ್ಲಿ, ನಿಮಗೆ ನಮ್ಮ ಒಟ್ಟು ಹೊಣೆಗಾರಿಕೆ ಎಂದರೆ ಹಕ್ಕು ಮಂಡಿಸುವುದಕ್ಕೂ ಮುಂಚಿನ 12 ತಿಂಗಳಲ್ಲಿ ನೀವು ಪಾವತಿಸಿದ ಸದಸ್ಯತ್ವ ಶುಲ್ಕಗಳು ಅಥವಾ 50 ಅಮೆರಿಕನ್ ಡಾಲರ್—ಇವೆರಡರಲ್ಲಿ ಯಾವುದು ಹೆಚ್ಚೋ ಅದಕ್ಕೆ ಮಿತಿಯಾಗಿರುತ್ತದೆ.",
        "ಕಾನೂನು ಹೊರತುಪಡಿಸಲು ಅಥವಾ ಮಿತಿಗೊಳಿಸಲು ಅನುಮತಿಸದ ಹೊಣೆಗಾರಿಕೆಯನ್ನು ಈ ಒಪ್ಪಂದದ ಯಾವುದೂ ಹೊರತುಪಡಿಸುವುದಿಲ್ಲ ಅಥವಾ ಮಿತಿಗೊಳಿಸುವುದಿಲ್ಲ. ಅನೇಕ ದೇಶಗಳಲ್ಲಿ ನಿರ್ಲಕ್ಷ್ಯದಿಂದ ಉಂಟಾದ ಮರಣ ಅಥವಾ ದೈಹಿಕ ಗಾಯದ ಹೊಣೆಗಾರಿಕೆ, ವಂಚನೆ ಅಥವಾ ಮೋಸದ ತಪ್ಪು ನಿರೂಪಣೆ ಮತ್ತು ಕಡ್ಡಾಯ ಗ್ರಾಹಕ ಹಕ್ಕುಗಳು ಇದರಲ್ಲಿ ಸೇರಿವೆ. ಈ ವಿಭಾಗದ ಒಂದು ಭಾಗ ಜಾರಿಗೊಳಿಸಲಾಗದು ಎಂದು ನ್ಯಾಯಾಲಯ ತೀರ್ಮಾನಿಸಿದರೂ ಉಳಿದ ಭಾಗ ಅನ್ವಯಿಸುತ್ತದೆ ಮತ್ತು ನಿಮ್ಮ ಕಡ್ಡಾಯ ಸ್ಥಳೀಯ ಹಕ್ಕುಗಳಿಗೆ ಧಕ್ಕೆಯಾಗುವುದಿಲ್ಲ.",
        "ಪರಿಹಾರ ಹೊಣೆ",
        "ನಿಮ್ಮ ವಿಷಯ, ವರ್ತನೆ, ಇತರ ಬಳಕೆದಾರರೊಂದಿಗಿನ ಏರ್ಪಾಟು ಅಥವಾ ಈ ಒಪ್ಪಂದದ ಉಲ್ಲಂಘನೆಯಿಂದ ಉಂಟಾಗಿ ಮೂರನೇ ವ್ಯಕ್ತಿ ಸಲ್ಲಿಸುವ ಹಕ್ಕು, ಬೇಡಿಕೆ, ನಷ್ಟ ಮತ್ತು ಸಮಂಜಸ ವೆಚ್ಚಗಳಿಂದ Go and Help ಗೆ ಪರಿಹಾರ ನೀಡಲು ಮತ್ತು ಅದನ್ನು ಹೊಣೆಗಾರಿಕೆಯಿಂದ ರಕ್ಷಿಸಲು ನೀವು ಒಪ್ಪುತ್ತೀರಿ—ನೀವು ವಾಸಿಸುವ ಸ್ಥಳದ ಕಾನೂನು ಇದನ್ನು ಅನುಮತಿಸದ ಮಟ್ಟಿಗೆ ಅಥವಾ ಹಕ್ಕು ನಮ್ಮದೇ ತಪ್ಪಿನಿಂದ ಉಂಟಾದರೆ ಇದು ಅನ್ವಯಿಸುವುದಿಲ್ಲ.",
        "ವಿವಾದಗಳು ಮತ್ತು ನಿಮ್ಮ ಸ್ಥಳೀಯ ಹಕ್ಕುಗಳು",
        "ಮೊದಲು ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ: ಹೆಚ್ಚಿನ ಸಮಸ್ಯೆಗಳು ಇಮೇಲ್ ಮೂಲಕ ಪರಿಹಾರವಾಗುತ್ತವೆ. ಪರಿಹರಿಸಲಾಗದಿದ್ದರೆ, ಯಾರಾದರೂ ನ್ಯಾಯಾಲಯಕ್ಕೆ ಹೋಗುವ ಮೊದಲು ಪ್ರಾಯೋಗಿಕ ಮುಂದಿನ ಹೆಜ್ಜೆಗೆ ಸದುದ್ದೇಶದಿಂದ ಒಪ್ಪಿಕೊಳ್ಳಲು ಪ್ರಯತ್ನಿಸುತ್ತೇವೆ.",
        "ಬಳಕೆದಾರರ ನಡುವಿನ ವಿವಾದಗಳು ಅವರದೇ. ಕಾನೂನು ಕೇಳಿದರೆ ದಾಖಲೆಗಳನ್ನು ಒದಗಿಸಬಹುದು; ಆದರೆ ನಾವು ಮಧ್ಯಸ್ಥಿಕೆ ವಹಿಸುವುದಿಲ್ಲ, ತೀರ್ಪು ನೀಡುವುದಿಲ್ಲ ಅಥವಾ ಪರಿಹಾರ ಪಾವತಿಸುವುದಿಲ್ಲ.",
        "ಈ ಒಪ್ಪಂದವು Go and Help ವೆಬ್‌ಸೈಟ್‌ನಲ್ಲಿ ಹೇಳಿರುವ ಕಾನೂನಿನಡಿ ನಿಯಂತ್ರಿತವಾಗಿರುತ್ತದೆ. ಆದರೆ ನೀವು ಗ್ರಾಹಕರಾಗಿದ್ದರೆ, ನೀವು ಸಾಮಾನ್ಯವಾಗಿ ವಾಸಿಸುವ ದೇಶದ ಕಡ್ಡಾಯ ಗ್ರಾಹಕ ಕಾನೂನಿನ ರಕ್ಷಣೆ ಅಥವಾ ನಿಮ್ಮ ಸ್ಥಳೀಯ ನ್ಯಾಯಾಲಯಗಳಲ್ಲಿ ದಾವೆ ಹೂಡುವ ಹಕ್ಕನ್ನು ಇಲ್ಲಿನ ಯಾವುದೂ ಕಸಿದುಕೊಳ್ಳುವುದಿಲ್ಲ. ಈ ಒಪ್ಪಂದದ ನಿಯಮವು ಅಂತಹ ಕಡ್ಡಾಯ ನಿಯಮಕ್ಕೆ ವಿರುದ್ಧವಾದರೆ ಕಡ್ಡಾಯ ನಿಯಮವೇ ಮೇಲುಗೈ ಸಾಧಿಸುತ್ತದೆ.",
        "ಈ ಒಪ್ಪಂದದ ಬದಲಾವಣೆಗಳು",
        "ಅಪ್ಲಿಕೇಶನ್ ಬದಲಾದಾಗ ಅಥವಾ ಕಾನೂನು ಕೇಳಿದಾಗ ಈ ಒಪ್ಪಂದವನ್ನು ನವೀಕರಿಸಬಹುದು. ಮಹತ್ವದ ಬದಲಾವಣೆಯಾದರೆ ಹೊಸ ಜಾರಿಗೆ ಬರುವ ದಿನಾಂಕವನ್ನು ಇಲ್ಲಿ ತೋರಿಸುತ್ತೇವೆ ಮತ್ತು ಗಮನಾರ್ಹ ಬದಲಾವಣೆಗಳ ಬಗ್ಗೆ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿ ತಿಳಿಸುತ್ತೇವೆ. ಬದಲಾವಣೆಯ ನಂತರವೂ Go and Help ಬಳಸುವುದನ್ನು ಮುಂದುವರಿಸಿದರೆ ನವೀಕರಿಸಿದ ನಿಯಮಗಳನ್ನು ಒಪ್ಪಿಕೊಂಡಂತೆ; ಒಪ್ಪದಿದ್ದರೆ ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಮುಚ್ಚಿ.",
        "ಈ ಪರದೆಗಳು ಅಂತರರಾಷ್ಟ್ರೀಯ ಬಳಕೆದಾರರಿಗಾಗಿ ರೂಪಿಸಿದ ಅಪ್ಲಿಕೇಶನ್ ವಿಷಯ. ಇವು ಯಾವುದೇ ನಿರ್ದಿಷ್ಟ ದೇಶದ ಕಾನೂನು ಸಲಹೆಯಲ್ಲ ಮತ್ತು ನೀವು ವಾಸಿಸುವ ಸ್ಥಳದ ಅರ್ಹ ವಕೀಲರ ಸಲಹೆಗೆ ಪರ್ಯಾಯವಲ್ಲ.",
    ),
}
